<?php
require_once __DIR__ . '/../../includes/admin_auth.php';require_admin();$id=valid_id($_GET['id']??$_POST['id']??null);if($id===null)redirect('index.php');$get=$pdo->prepare('SELECT * FROM contact_messages WHERE id=:id LIMIT 1');$get->execute(['id'=>$id]);$message=$get->fetch();if(!$message)redirect('index.php');if(is_post_request()){if(!verify_csrf_token($_POST['csrf_token']??null))exit('Invalid request.');$newStatus=post_string('status',20);if(in_array($newStatus,['read','unread'],true)){$update=$pdo->prepare('UPDATE contact_messages SET status=:status WHERE id=:id');$update->execute(['status'=>$newStatus,'id'=>$id]);}$message['status']=$newStatus;}admin_header('Message Details','messages/index.php');?><div class="card table-card"><div class="card-body p-4"><div class="d-flex justify-content-between mb-4"><h2 class="h5">Message Details</h2><span class="badge text-bg-<?=strtolower($message['status'])==='unread'?'danger':'secondary'?>"><?=e(ucfirst($message['status']))?></span></div><div class="row g-4"><div class="col-md-6"><small class="text-secondary d-block">Name</small><strong><?=e($message['name'])?></strong></div><div class="col-md-6"><small class="text-secondary d-block">Email</small><strong><?=e($message['email'])?></strong></div><div class="col-md-6"><small class="text-secondary d-block">Phone</small><strong><?=e($message['phone']?:'—')?></strong></div><div class="col-md-6"><small class="text-secondary d-block">Subject</small><strong><?=e($message['subject'])?></strong></div><div class="col-12"><small class="text-secondary d-block">Message</small><p class="mt-2"><?=nl2br(e($message['message']))?></p></div><div class="col-12"><small class="text-secondary d-block">Date</small><p><?=e(date('d M Y, h:i A',strtotime($message['created_at'])))?></p></div></div><form method="post" class="d-inline"><input type="hidden" name="id" value="<?=e($id)?>"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="status" value="<?=strtolower($message['status'])==='unread'?'read':'unread'?>"><button class="btn btn-outline-primary" type="submit"><?=strtolower($message['status'])==='unread'?'Mark Read':'Mark Unread'?></button></form><a class="btn btn-outline-secondary ms-2" href="index.php">Back</a></div></div><?php admin_footer();?>
